const CREST="data:image/png;base64,";
const BRAND_KEY="sc_brand_settings_final";
const ACCESS_KEY="sc_access_settings_final";
const DB_NAME="SneakersCoFinal";
const DB_STORE="catalogue";

let products=PRODUCTS.map((p,i)=>({...p,ref:i+1}));
let currentImages=[];
let currentCover=0;
let editingId=null;

function openWhatsApp(message){
  const encodedMessage=encodeURIComponent(message);
  const url=`https://wa.me/919212356000?text=${encodedMessage}`;
  window.location.href=url;
}

function esc(v=""){return String(v).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function toast(msg){const el=document.querySelector("#toast span");if(!el)return;el.textContent=msg;const t=document.getElementById("toast");t.classList.add("show");clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove("show"),2200)}

function accessSettings(){
  try{return Object.assign({adminPassword:"SNC-HOUSE-2026",privateEnabled:false,privateCode:""},JSON.parse(localStorage.getItem(ACCESS_KEY)||"{}"))}
  catch{return {adminPassword:"SNC-HOUSE-2026",privateEnabled:false,privateCode:""}}
}
function saveAccessSettings(v){localStorage.setItem(ACCESS_KEY,JSON.stringify(v))}

function brandSettings(){
  try{return Object.assign({logo:"",crest:CREST,whatsapp:CONFIG.WHATSAPP_NUMBER,instagram:CONFIG.INSTAGRAM_URL,brandName:"SNEAKERS & CO."},JSON.parse(localStorage.getItem(BRAND_KEY)||"{}"))}
  catch{return {logo:"",crest:CREST,whatsapp:CONFIG.WHATSAPP_NUMBER,instagram:CONFIG.INSTAGRAM_URL,brandName:"SNEAKERS & CO."}}
}
function saveBrandSettings(v){localStorage.setItem(BRAND_KEY,JSON.stringify(v))}

function applyBrand(){
  const s=brandSettings();
  CONFIG.WHATSAPP_NUMBER=(s.whatsapp||CONFIG.WHATSAPP_NUMBER).replace(/\D/g,"");
  CONFIG.INSTAGRAM_URL=s.instagram||CONFIG.INSTAGRAM_URL;
  document.querySelectorAll(".crest-img").forEach(i=>i.src=s.crest||CREST);
  const navBrand=document.querySelector(".brand");
  if(navBrand){
    navBrand.innerHTML=`<img src="${esc(s.logo||s.crest||CREST)}" alt="${esc(s.brandName)}"><span>${esc(s.brandName)}</span>`;
  }
  const ig=document.getElementById("footerInstagram");
  if(ig){ig.href=CONFIG.INSTAGRAM_URL;ig.target="_blank";ig.rel="noopener"}
  const wa=document.getElementById("footerWhatsApp");
  if(wa){wa.href=`https://wa.me/${CONFIG.WHATSAPP_NUMBER}`;wa.target="_blank";wa.rel="noopener"}
}

function idbOpen(){
  return new Promise((resolve,reject)=>{
    const r=indexedDB.open(DB_NAME,1);
    r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(DB_STORE))r.result.createObjectStore(DB_STORE)};
    r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);
  })
}
async function dbRead(){
  try{
    const db=await idbOpen();
    return await new Promise((res,rej)=>{
      const tx=db.transaction(DB_STORE,"readonly"); const q=tx.objectStore(DB_STORE).get("products");
      q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)
    })
  }catch{return null}
}
async function dbWrite(value){
  try{
    const db=await idbOpen();
    await new Promise((res,rej)=>{
      const tx=db.transaction(DB_STORE,"readwrite");tx.objectStore(DB_STORE).put(value,"products");tx.oncomplete=res;tx.onerror=()=>rej(tx.error)
    })
  }catch{
    localStorage.setItem("sc_catalogue_fallback",JSON.stringify(value))
  }
}
async function loadProducts(){
  let saved=await dbRead();
  if(!Array.isArray(saved)){
    try{saved=JSON.parse(localStorage.getItem("sc_catalogue_fallback")||"null")}catch{}
  }

  if(Array.isArray(saved) && saved.length){
    // Migrate older catalogue records so older versions cannot make
    // Current Edit disappear simply because "featured" was missing.
    products=saved.map((p,i)=>({
      ...p,
      ref:Number(p.ref)||i+1,
      featured:p.featured===true
    }));

    // If an older catalogue contains products but none are featured,
    // use the first six as the initial Current Edit. The user can then
    // control Featured ON/OFF from House Desk.
    if(!products.some(p=>p.featured===true)){
      products=products.map((p,i)=>({...p,featured:i<Math.min(6,products.length)}));
      await dbWrite(products);
    }
  } else {
    // Keep the built-in catalogue available on a fresh/local reset.
    products=PRODUCTS.map((p,i)=>({...p,ref:Number(p.ref)||i+1,featured:p.featured===true}));
  }

  PRODUCTS.splice(0, PRODUCTS.length, ...products);
  renderAll();
}

function nextRef(){return Math.max(0,...products.map(p=>Number(p.ref)||0))+1}

function productPlaceholder(p){
  return `<div class="placeholder"><div class="placeholder-inner"><span class="tech">S&amp;C / PIECE ${String(p.ref||1).padStart(3,"0")}</span><strong>${esc(p.brand)}</strong><span class="tech">${esc(p.name)}</span></div></div>`
}
function productImage(p){
  if(p.images&&p.images.length) return `<img src="${p.images[Math.min(p.cover||0,p.images.length-1)].data}" alt="${esc(p.brand+" "+p.name)}">`;
  return productPlaceholder(p)
}
function card(p){
  return `<article class="product-card">
    <button type="button" class="product-image" data-product-id="${esc(p.id)}">${productImage(p)}</button>
    <div class="product-meta">
      <div class="product-brand">${esc(p.brand)}</div>
      <div class="product-name">${esc(p.name)}</div>
      <div class="product-status">${esc(p.status)}</div>
      <div class="product-actions">
        <button type="button" class="link" data-product-id="${esc(p.id)}">VIEW PIECE →</button>
        <button type="button" class="iconbtn" data-wa-product="${esc(p.id)}">↗</button>
      </div>
    </div>
  </article>`
}

function renderCurrent(){
  const featuredProducts = PRODUCTS.filter(p => p.featured);
  const arr=featuredProducts.slice(0,6);
  document.getElementById("currentCount").textContent=`${arr.length} PIECES`;
  document.getElementById("currentGrid").innerHTML=arr.map(card).join("")||"<div style='grid-column:1/-1;padding:50px 20px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)'><div class='kicker'>CURRENT EDIT</div><div style='font:500 34px var(--display);margin-top:12px'>The next edit is being prepared.</div></div>";
}
function renderAll(){renderCurrent();renderDesk()}

function openProduct(id){
  const p=products.find(x=>x.id===id);if(!p)return;
  document.getElementById("modalTitle").textContent=`${p.brand} · ${p.name}`;
  const gallery=(p.images||[]).map((im,i)=>`<button type="button" onclick="showDetailImage(${i})"><img src="${im.data}" alt=""></button>`).join("");
  document.getElementById("productDetail").innerHTML=`
    <div class="product-detail">
      <div>
        <div class="detail-main" id="detailMain">${productImage(p)}</div>
        ${gallery?`<div class="detail-thumbs">${gallery}</div>`:""}
      </div>
      <div class="detail">
        <div class="kicker">S&amp;C / PIECE ${String(p.ref).padStart(3,"0")}</div>
        <div class="product-brand" style="margin-top:15px">${esc(p.brand)}</div>
        <h1>${esc(p.name)}</h1>
        <div class="product-status">${esc(p.status)}</div>
        <div class="desc">${esc(p.description||"")}</div>
        <div class="detail-meta">
          ${[["Category",p.category],["Subcategory",p.subcategory],["Colour",p.colour],["Material",p.material],["Size",p.size],["Reference",p.reference],["Included",p.included]].filter(x=>x[1]).map(x=>`<div><span>${esc(x[0])}</span><span>${esc(x[1])}</span></div>`).join("")}
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:24px">
          <button class="btn solid" type="button" id="productWA">ENQUIRE ON WHATSAPP →</button>
        </div>
      </div>
    </div>`;
  document.getElementById("productModal").classList.add("open");
  document.getElementById("productModal").setAttribute("aria-hidden","false");
  document.getElementById("productWA").onclick=()=>openWhatsApp(`Hello Sneakers & Co., I’m interested in the ${p.brand} ${p.name}. Could you share availability and details?`);
  window.__detailImages=p.images||[];
}
function showDetailImage(i){const im=window.__detailImages?.[i];if(im)document.getElementById("detailMain").innerHTML=`<img src="${im.data}" alt="">`}
function closeProduct(){document.getElementById("productModal").classList.remove("open");document.getElementById("productModal").setAttribute("aria-hidden","true")}

function categoryWhatsApp(category){
  const msg={
    Bags:"Hello Sneakers & Co., I’d like to enquire about a handbag.",
    Watches:"Hello Sneakers & Co., I’d like to enquire about a watch.",
    Accessories:"Hello Sneakers & Co., I’d like to enquire about an accessory.",
    Fashion:"Hello Sneakers & Co., I’d like to enquire about fashion.",
    Sneakers:"Hello Sneakers & Co., I’d like to enquire about sneakers."
  }[category]||"Hello Sneakers & Co., I’d like to make a private sourcing request.";
  openWhatsApp(msg)
}

/* HOUSE DESK */

function closeDesk(){
  const desk=document.getElementById("deskModal");
  if(!desk)return;
  desk.classList.remove("open");
  desk.setAttribute("aria-hidden","true");
  document.body.style.overflow="";
}
function showDesk(tab="catalogue"){
  if(sessionStorage.getItem("sc_house_auth")!=="1"){openAdminGate();return}
  document.getElementById("deskModal").classList.add("open");
  document.getElementById("deskModal").setAttribute("aria-hidden","false");
  document.body.style.overflow="hidden";
  switchDesk(tab)
}
function openAdminGate(){
  const gate=document.getElementById("houseDeskPassModal");
  const input=document.getElementById("houseDeskPassInput");
  const error=document.getElementById("houseDeskPassError");
  if(!gate||!input)return;
  input.value="";
  if(error)error.textContent="";
  gate.classList.add("open");
  gate.setAttribute("aria-hidden","false");
  document.body.classList.add("sc-house-lock");
  document.body.style.overflow="hidden";
  setTimeout(()=>input.focus(),80);
}
function switchDesk(tab){
  document.querySelectorAll(".desk-tab").forEach(b=>b.classList.toggle("active",b.dataset.deskTab===tab));
  document.getElementById("deskCatalogue").style.display=tab==="catalogue"?"block":"none";
  document.getElementById("deskEditor").style.display=tab==="editor"?"block":"none";
  document.getElementById("deskSettings").style.display=tab==="settings"?"block":"none";
  if(tab==="editor"&&!editingId)resetEditor();
  if(tab==="settings")syncSettings()
}
function renderDesk(){
  document.getElementById("deskStats").innerHTML=`<div class="stat"><b>${products.length}</b><span>TOTAL PIECES</span></div>`+CONFIG.categories.map(c=>`<div class="stat"><b>${products.filter(p=>p.category===c).length}</b><span>${c}</span></div>`).join("");
  document.getElementById("deskCategory").innerHTML='<option value="">ALL CATEGORIES</option>'+CONFIG.categories.map(c=>`<option>${c}</option>`).join("");
  document.getElementById("deskStatus").innerHTML='<option value="">ALL STATUS</option>'+CONFIG.statuses.map(s=>`<option>${s}</option>`).join("");
  renderDeskList()
}
function renderDeskList(){
  const q=document.getElementById("deskSearch").value.toLowerCase().trim();
  const cat=document.getElementById("deskCategory").value;
  const st=document.getElementById("deskStatus").value;
  const arr=products.filter(p=>(!q||[p.brand,p.name,p.category,p.subcategory].join(" ").toLowerCase().includes(q))&&(!cat||p.category===cat)&&(!st||p.status===st));
  document.getElementById("deskList").innerHTML=arr.map(p=>`<div class="desk-row"><div><strong>${esc(p.brand)} — ${esc(p.name)}</strong><small>S&amp;C / PIECE ${String(p.ref).padStart(3,"0")} · ${esc(p.category)} · ${esc(p.subcategory)}</small></div><div class="product-status">${esc(p.status)}</div><div class="tech">${p.images?.length||0} IMAGES${p.featured?" · FEATURED":""}</div><div class="actions"><button class="btn" data-edit="${esc(p.id)}">EDIT</button><button class="btn" data-duplicate="${esc(p.id)}">DUPLICATE</button><button class="btn" data-delete="${esc(p.id)}">DELETE</button></div></div>`).join("")||"<div style='padding:30px;color:var(--muted)'>No pieces match.</div>"
}
function fillEditorSelects(){
  document.getElementById("formCategory").innerHTML=CONFIG.categories.map(c=>`<option>${c}</option>`).join("");
  document.getElementById("formStatus").innerHTML=CONFIG.statuses.map(s=>`<option>${s}</option>`).join("");
  updateSubcategories()
}
function updateSubcategories(){const c=document.getElementById("formCategory").value;document.getElementById("formSubcategory").innerHTML=(CONFIG.subcategories[c]||["Other"]).map(s=>`<option>${s}</option>`).join("")}
function resetEditor(){
  editingId=null;currentImages=[];currentCover=0;document.getElementById("productForm").reset();fillEditorSelects();renderThumbs()
}
function editProduct(id){
  const p=products.find(x=>x.id===id);if(!p)return;editingId=id;currentImages=JSON.parse(JSON.stringify(p.images||[]));currentCover=p.cover||0;
  const f=document.getElementById("productForm");
  f.brand.value=p.brand;f.name.value=p.name;f.category.value=p.category;updateSubcategories();f.subcategory.value=p.subcategory;f.status.value=p.status;f.description.value=p.description||"";f.colour.value=p.colour||"";f.material.value=p.material||"";f.size.value=p.size||"";f.reference.value=p.reference||"";f.included.value=p.included||"";f.featured.checked=!!p.featured;
  switchDesk("editor");renderThumbs()
}
function renderThumbs(){
  document.getElementById("imageThumbs").innerHTML=currentImages.map((im,i)=>`<div class="thumb" draggable="true"><img src="${im.data}" alt=""><button type="button" data-remove-image="${i}">×</button></div>`).join("")
}
function saveProduct(e){
  e.preventDefault();
  const f=e.target;const old=editingId?products.find(p=>p.id===editingId):null;
  const id=editingId||(f.brand.value+"-"+f.name.value).toLowerCase().replace(/[^a-z0-9]+/g,"-")+"-"+Date.now();
  const p={id,ref:old?.ref||nextRef(),brand:f.brand.value.trim(),name:f.name.value.trim(),category:f.category.value,subcategory:f.subcategory.value,status:f.status.value,description:f.description.value.trim(),colour:f.colour.value.trim(),material:f.material.value.trim(),size:f.size.value.trim(),reference:f.reference.value.trim(),included:f.included.value.trim(),featured:f.featured.checked,images:currentImages,cover:currentCover};
  products=old?products.map(x=>x.id===id?p:x):[...products,p];
  PRODUCTS.splice(0, PRODUCTS.length, ...products);
  dbWrite(products).then(()=>{renderAll();switchDesk("catalogue");toast("PIECE SAVED")}).catch(()=>toast("SAVE FAILED"))
}
async function handleFiles(files){
  for(const file of files){
    const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});
    currentImages.push({name:file.name,data})
  }
  renderThumbs()
}

/* SETTINGS */
function syncSettings(){
  const b=brandSettings(); const a=accessSettings();
  document.getElementById("settingsWhatsApp").value=b.whatsapp;
  document.getElementById("settingsInstagram").value=b.instagram;
  document.getElementById("settingsBrandName").value=b.brandName;
  document.getElementById("settingsLogoPreview").src=b.logo||b.crest||CREST;
  document.getElementById("settingsCrestPreview").src=b.crest||CREST;
  document.getElementById("privateAccessEnabled").checked=!!a.privateEnabled;
  document.getElementById("privateAccessCode").value=a.privateCode||"";
}
async function fileData(file){return await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function saveHouseSettings(){
  const b=brandSettings();
  b.whatsapp=document.getElementById("settingsWhatsApp").value.trim();
  b.instagram=document.getElementById("settingsInstagram").value.trim();
  b.brandName=document.getElementById("settingsBrandName").value.trim()||"SNEAKERS & CO.";
  const p1=document.getElementById("adminPassword1").value.trim(),p2=document.getElementById("adminPassword2").value.trim();
  if(p1||p2){if(p1!==p2){toast("PASSWORDS DO NOT MATCH");return}saveAccessSettings({...accessSettings(),adminPassword:p1})}
  saveBrandSettings(b);applyBrand();syncSettings()
}
function savePrivateAccess(){
  const a=accessSettings();const enabled=document.getElementById("privateAccessEnabled").checked;const code=document.getElementById("privateAccessCode").value.trim();
  if(enabled&&!code){toast("ADD A PRIVATE ACCESS CODE");return}
  saveAccessSettings({...a,privateEnabled:enabled,privateCode:code});
  sessionStorage.removeItem("sc_customer_auth");
  syncPrivateGate()
}
function syncPrivateGate(){
  const a=accessSettings();const g=document.getElementById("privateCustomerGate");
  if(a.privateEnabled&&sessionStorage.getItem("sc_customer_auth")!=="1"){g.classList.add("open");document.body.style.overflow="hidden"}else{g.classList.remove("open");document.body.style.overflow=""}
}

/* EVENTS */
document.getElementById("mobileMenuBtn").addEventListener("click",()=>{document.getElementById("mobileMenu").style.display="block";document.body.style.overflow="hidden"});
document.getElementById("mobileMenuClose").addEventListener("click",()=>{document.getElementById("mobileMenu").style.display="none";document.body.style.overflow=""});
document.querySelectorAll(".mobile-nav-link").forEach(a=>a.addEventListener("click",()=>{document.getElementById("mobileMenu").style.display="none";document.body.style.overflow=""}));
document.getElementById("closeProduct").addEventListener("click",closeProduct);
document.getElementById("closeDesk").addEventListener("click",closeDesk);
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&document.getElementById("deskModal")?.classList.contains("open"))closeDesk()});
document.querySelectorAll(".desk-tab").forEach(b=>b.addEventListener("click",()=>switchDesk(b.dataset.deskTab)));
document.getElementById("formCategory").addEventListener("change",updateSubcategories);
document.getElementById("productForm").addEventListener("submit",saveProduct);
document.getElementById("imageInput").addEventListener("change",e=>handleFiles([...e.target.files]));
document.getElementById("cancelEdit").addEventListener("click",()=>switchDesk("catalogue"));
document.getElementById("deskSearch").addEventListener("input",renderDeskList);
document.getElementById("deskCategory").addEventListener("change",renderDeskList);
document.getElementById("deskStatus").addEventListener("change",renderDeskList);
document.addEventListener("click",e=>{const c=e.target.closest?.("[data-category-wa]")?.dataset.categoryWa;if(c)categoryWhatsApp(c)});
document.addEventListener("click",e=>{
  const pid=e.target.closest?.("[data-product-id]")?.dataset.productId;
  if(pid)openProduct(pid);
  const wa=e.target.closest?.("[data-wa-product]")?.dataset.waProduct;
  if(wa){const p=products.find(x=>x.id===wa);if(p)openWhatsApp(`Hello Sneakers & Co., I’m interested in the ${p.brand} ${p.name}. Could you share availability and details?`)}
  const ed=e.target.closest?.("[data-edit]")?.dataset.edit;if(ed)editProduct(ed);
  const dup=e.target.closest?.("[data-duplicate]")?.dataset.duplicate;if(dup){const p=products.find(x=>x.id===dup);if(p){products.push({...JSON.parse(JSON.stringify(p)),id:p.id+"-"+Date.now(),ref:nextRef()});PRODUCTS.splice(0, PRODUCTS.length, ...products);dbWrite(products).then(renderAll)}}
  const del=e.target.closest?.("[data-delete]")?.dataset.delete;if(del&&confirm("REMOVE THIS PIECE?")){products=products.filter(p=>p.id!==del);PRODUCTS.splice(0, PRODUCTS.length, ...products);dbWrite(products).then(renderAll)}
});

document.getElementById("requestForm").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);openWhatsApp(`Hello Sneakers & Co., I’d like to make a private sourcing request. I’m looking for a specific piece.\n\nName: ${f.get("name")}\nWhatsApp: ${f.get("phone")}\nCategory: ${f.get("category")}\nBrand / Piece: ${f.get("piece")}\nDetails: ${f.get("details")}`)});
document.getElementById("footerInstagram").addEventListener("click",()=>{document.getElementById("footerInstagram").href=brandSettings().instagram||CONFIG.INSTAGRAM_URL});
document.getElementById("privateAccessTrigger").addEventListener("click",showDesk);
document.getElementById("saveBrandSettings").addEventListener("click",function(e){e.preventDefault();try{saveHouseSettings()}catch(err){console.error(err);toast("HOUSE SETTINGS SAVE FAILED")}});
document.getElementById("savePrivateAccess").addEventListener("click",function(e){e.preventDefault();try{savePrivateAccess()}catch(err){console.error(err);toast("PRIVATE ACCESS SAVE FAILED")}});
document.getElementById("customerAccessEnter").addEventListener("click",()=>{const a=accessSettings();if(document.getElementById("customerAccessInput").value.trim()===a.privateCode){sessionStorage.setItem("sc_customer_auth","1");syncPrivateGate()}else document.getElementById("customerAccessError").style.display="block"});
document.getElementById("customerAccessInput").addEventListener("keydown",e=>{if(e.key==="Enter")document.getElementById("customerAccessEnter").click()});
document.getElementById("settingsLogoInput").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;const b=brandSettings();b.logo=await fileData(f);saveBrandSettings(b);applyBrand();syncSettings();toast("LOGO UPLOADED")});
document.getElementById("settingsCrestInput").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;const b=brandSettings();b.crest=await fileData(f);saveBrandSettings(b);applyBrand();syncSettings();toast("CREST UPLOADED")});
document.getElementById("removeLogo").addEventListener("click",()=>{const b=brandSettings();b.logo="";saveBrandSettings(b);applyBrand();syncSettings();toast("TEXT WORDMARK RESTORED")});
document.getElementById("imageThumbs").addEventListener("click",e=>{const r=e.target.closest("[data-remove-image]");if(r){currentImages.splice(Number(r.dataset.removeImage),1);currentCover=Math.min(currentCover,Math.max(currentImages.length-1,0));renderThumbs()}});
document.getElementById("exportCatalogue").addEventListener("click",()=>{const blob=new Blob([JSON.stringify({products},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="sneakers-co-catalogue.json";a.click();URL.revokeObjectURL(a.href)});
document.getElementById("importCatalogue").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d.products))throw Error();products=d.products;await dbWrite(products);renderAll();toast("CATALOGUE IMPORTED")}catch{toast("IMPORT FAILED")}});

const drop=document.querySelector(".image-drop");
drop.addEventListener("dragover",e=>{e.preventDefault();drop.style.borderColor="var(--brass)"});
drop.addEventListener("dragleave",()=>drop.style.borderColor="");
drop.addEventListener("drop",e=>{e.preventDefault();drop.style.borderColor="";handleFiles([...e.dataTransfer.files].filter(f=>f.type.startsWith("image/")))})

document.addEventListener("DOMContentLoaded",function(){
  try{
    if(typeof fillEditorSelects==="function") fillEditorSelects();
    if(typeof applyBrand==="function") applyBrand();
    if(typeof loadProducts==="function") loadProducts();
    if(typeof syncSettings==="function") syncSettings();
    if(typeof syncPrivateGate==="function") syncPrivateGate();
  }catch(err){
    console.error("S&C bootstrap error",err);
  }
});

document.addEventListener("DOMContentLoaded",function(){
  const modal=document.getElementById("houseDeskPassModal");
  const input=document.getElementById("houseDeskPassInput");
  const error=document.getElementById("houseDeskPassError");
  const submit=document.getElementById("houseDeskPassSubmit");

  function closeGate(){
    if(!modal)return;
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden","true");
    document.body.classList.remove("sc-house-lock");
    document.body.style.overflow="";
  }

  function submitGate(){
    if(!input)return;
    const a=accessSettings();
    const entered=(input.value||"").trim();
    if(entered===a.adminPassword){
      sessionStorage.setItem("sc_house_auth","1");
      if(error)error.textContent="";
      closeGate();
      showDesk("catalogue");
      toast("HOUSE DESK OPEN");
    }else{
      if(error)error.textContent="PASSWORD NOT RECOGNISED";
      input.select();
    }
  }

  submit?.addEventListener("click",submitGate);
  input?.addEventListener("keydown",function(e){
    if(e.key==="Enter"){e.preventDefault();submitGate()}
    if(e.key==="Escape"){e.preventDefault();closeGate()}
  });
  modal?.querySelectorAll("[data-house-pass-close]").forEach(el=>el.addEventListener("click",closeGate));
  document.addEventListener("keydown",function(e){
    if(e.key==="Escape" && modal?.classList.contains("open"))closeGate();
  });
});

(function(){
 const view=document.getElementById("combinedFullEdit"),grid=document.getElementById("combinedFullGrid"),filters=document.getElementById("combinedFullFilters"),search=document.getElementById("combinedFullSearch"),count=document.getElementById("combinedFullCount");
 if(!view||!grid||!filters||!search||!count)return;
 let activeCategory="ALL";
 let homeScrollY=0;
 let fullEditOpen=false;
 function cleanHomeUrl(){
   const clean=location.pathname+(location.hash && location.hash!=="#full-edit" ? location.hash : "");
   history.replaceState({view:"home"},"",clean);
 }
 function openFullEdit(category="ALL",updateHistory=true){
   activeCategory=category||"ALL";
   homeScrollY=window.scrollY||0;
   fullEditOpen=true;
   document.body.classList.add("sc-full-edit-open");
   document.documentElement.classList.add("sc-full-edit-open");
   view.setAttribute("aria-hidden","false");
   renderFilters();
   renderFull();
   view.scrollTop=0;
   if(updateHistory){
     history.pushState({view:"full",category:activeCategory},"",location.pathname+"?view=full"+(activeCategory!=="ALL"?"&category="+encodeURIComponent(activeCategory):""));
   }
 }
 function closeFullEdit(){
   fullEditOpen=false;
   document.body.classList.remove("sc-full-edit-open");
   document.documentElement.classList.remove("sc-full-edit-open");
   view.setAttribute("aria-hidden","true");
   view.scrollTop=0;
   cleanHomeUrl();
   requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:"auto"}));
 }
 function renderFilters(){const cats=["ALL",...Array.from(new Set(products.map(p=>p.category).filter(Boolean))).sort()];filters.innerHTML=cats.map(c=>`<button class="filter ${c===activeCategory?"active":""}" type="button" data-full-category="${esc(c)}">${esc(c)}</button>`).join("");}
 function renderFull(){const q=(search.value||"").trim().toLowerCase();let arr=products.slice();if(activeCategory!=="ALL")arr=arr.filter(p=>p.category===activeCategory);if(q)arr=arr.filter(p=>[p.brand,p.name,p.category,p.subcategory,p.status,p.description].join(" ").toLowerCase().includes(q));count.textContent=`${arr.length} PIECES`;grid.innerHTML=arr.map(card).join("")||`<div style="grid-column:1/-1;padding:50px 20px"><div class="kicker">FULL EDIT</div><div style="font:500 34px var(--display);margin-top:12px">No pieces found.</div></div>`;}
 filters.addEventListener("click",e=>{const b=e.target.closest("[data-full-category]");if(!b)return;activeCategory=b.dataset.fullCategory;renderFilters();renderFull();});
 search.addEventListener("input",renderFull);
 document.getElementById("combinedBackHome")?.addEventListener("click",closeFullEdit);
 document.addEventListener("click",e=>{
   const link=e.target.closest?.("a[data-full-category],a[href='#full-edit']");
   if(!link)return;
   if(link.closest("#combinedFullEdit"))return;
   e.preventDefault();
   e.stopPropagation();
   openFullEdit(link.dataset.fullCategory||"ALL",true);
 },true);
 window.addEventListener("popstate",e=>{
   const params=new URLSearchParams(location.search);
   if(params.get("view")==="full"){
     openFullEdit(params.get("category")||"ALL",false);
   }else if(fullEditOpen){
     closeFullEdit();
   }
 });
 document.addEventListener("DOMContentLoaded",()=>{
   const params=new URLSearchParams(location.search);
   if(params.get("view")==="full")openFullEdit(params.get("category")||"ALL",false);
   else cleanHomeUrl();
 });
 window.__openCombinedFullEdit=openFullEdit;
})();
